/** Versioned, provider-independent cabinet observations. No money is generated by AI. */
export const PHOTO_ANALYSIS_MODEL = 'gpt-6.1-sol';
export const PHOTO_ANALYSIS_PROMPT_VERSION = 'cabinet-observations-v2';
export const PHOTO_ANALYSIS_SCHEMA_VERSION = 'cabinet-photo-analysis-v1';
export const AI_CONSENT_VERSION = 'openai-photo-analysis-v1';
export const PHOTO_ROLES = ['overview', 'upper', 'lower', 'side', 'damage'] as const;
export type PhotoRole = typeof PHOTO_ROLES[number];
export type AnalysisCoverage = { upperNotApplicable: boolean; damageNotPresent: boolean };
export interface PhotoAnalysis {
  summary: string;
  outcome: 'analysis_ready' | 'additional_photos_required' | 'site_review_required';
  photoQuality: { photoId: string; usable: boolean; issues: string[]; retakeInstruction: string | null }[];
  coverage: { role: PhotoRole; covered: boolean; photoIds: string[]; note: string }[];
  observedDamage: { id: string; kind: 'peeling' | 'chipping' | 'cracking' | 'swelling' | 'joint_gap' | 'other'; location: string; description: string; photoIds: string[]; severity: 'minor' | 'moderate' | 'severe' }[];
  quantities: { doors: AnalysisQuantity; drawers: AnalysisQuantity };
  proposedWork: { id: string; title: string; description: string; photoIds: string[]; repairIds: string[] }[];
  unknowns: string[];
  siteChecks: string[];
}
export interface AnalysisQuantity { observed: number | null; customer: number | null; needsConfirmation: boolean }
export interface AnalysisUsage {
  inputTokens: number; outputTokens: number; cachedInputTokens: number; reasoningTokens: number;
  totalTokens: number; estimatedCostUsd: number; rateVersion: string;
}
export class AnalysisValidationError extends Error {
  constructor() { super('The photo analysis could not be validated. Please try again or request company review.'); }
}

type RecordValue = Record<string, unknown>;
function object(value: unknown, keys: readonly string[]): RecordValue {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new AnalysisValidationError();
  const row = value as RecordValue;
  if (Object.keys(row).length !== keys.length || keys.some(key => !Object.hasOwn(row, key))) throw new AnalysisValidationError();
  return row;
}
function text(value: unknown, max = 1200): string {
  if (typeof value !== 'string' || !value.trim() || value.length > max || /[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(value) || /(?:\$\s*\d|\b(?:AUD|USD)\s*\d|\b\d[\d,.]*\s*(?:dollars|AUD|USD)\b)/i.test(value)) throw new AnalysisValidationError();
  return value.trim();
}
function list(value: unknown, max: number): unknown[] {
  if (!Array.isArray(value) || value.length > max) throw new AnalysisValidationError();
  return value;
}
function strings(value: unknown, max = 16): string[] { return list(value, max).map(item => text(item)); }
function bool(value: unknown): boolean { if (typeof value !== 'boolean') throw new AnalysisValidationError(); return value; }
function choice<T extends string>(value: unknown, options: readonly T[]): T {
  if (!options.includes(value as T)) throw new AnalysisValidationError(); return value as T;
}
function identifier(value: unknown): string { const id = text(value, 100); if (!/^[a-zA-Z0-9_-]+$/.test(id)) throw new AnalysisValidationError(); return id; }
function unique(items: string[]): void { if (new Set(items).size !== items.length) throw new AnalysisValidationError(); }
function quantity(value: unknown, customer: number | null): AnalysisQuantity {
  const row = object(value, ['observed', 'customer', 'needsConfirmation']);
  const observed = row.observed;
  if (observed !== null && (!Number.isInteger(observed) || (observed as number) < 0 || (observed as number) > 500)) throw new AnalysisValidationError();
  // The saved customer count is authoritative; do not trust the model to rewrite it.
  if (row.customer !== customer || typeof row.needsConfirmation !== 'boolean') throw new AnalysisValidationError();
  return { observed: observed as number | null, customer, needsConfirmation: observed === null || customer === null || observed !== customer || row.needsConfirmation };
}
export function validatePhotoAnalysis(value: unknown, context: { photoIds: string[]; doorCount: number | null; drawerCount: number | null; coverage: AnalysisCoverage }): PhotoAnalysis {
  const row = object(value, ['summary', 'outcome', 'photoQuality', 'coverage', 'observedDamage', 'quantities', 'proposedWork', 'unknowns', 'siteChecks']);
  unique(context.photoIds);
  const evidence = (value: unknown, required = true): string[] => {
    const ids = strings(value, 8); unique(ids);
    if ((required && !ids.length) || ids.some(id => !context.photoIds.includes(id))) throw new AnalysisValidationError();
    return ids;
  };
  const photoQuality = list(row.photoQuality, 8).map(value => {
    const item = object(value, ['photoId', 'usable', 'issues', 'retakeInstruction']);
    const photoId = text(item.photoId, 100), usable = bool(item.usable), issues = strings(item.issues, 8);
    const retakeInstruction = item.retakeInstruction === null ? null : text(item.retakeInstruction);
    if (!context.photoIds.includes(photoId) || (!usable && (!issues.length || !retakeInstruction))) throw new AnalysisValidationError();
    return {photoId, usable, issues, retakeInstruction};
  });
  unique(photoQuality.map(item => item.photoId));
  if (photoQuality.length !== context.photoIds.length) throw new AnalysisValidationError();
  const coverage = list(row.coverage, 5).map(value => {
    const item = object(value, ['role', 'covered', 'photoIds', 'note']);
    const role = choice(item.role, PHOTO_ROLES), covered = bool(item.covered), photoIds = evidence(item.photoIds, covered);
    if (covered && photoIds.some(id => !photoQuality.find(photo => photo.photoId === id)?.usable)) throw new AnalysisValidationError();
    return {role, covered, photoIds, note:text(item.note)};
  });
  unique(coverage.map(item => item.role));
  if (coverage.length !== PHOTO_ROLES.length) throw new AnalysisValidationError();
  const observedDamage = list(row.observedDamage, 30).map(value => {
    const item = object(value, ['id', 'kind', 'location', 'description', 'photoIds', 'severity']);
    return {id:identifier(item.id), kind:choice(item.kind, ['peeling','chipping','cracking','swelling','joint_gap','other'] as const), location:text(item.location,240), description:text(item.description), photoIds:evidence(item.photoIds), severity:choice(item.severity,['minor','moderate','severe'] as const)};
  });
  unique(observedDamage.map(item => item.id));
  // Catch duplicate repair descriptions even if the model assigned different IDs.
  unique(observedDamage.map(item => `${item.kind}:${item.location.toLowerCase().replace(/\s+/g, ' ')}`));
  const proposedWork = list(row.proposedWork, 30).map(value => {
    const item = object(value, ['id', 'title', 'description', 'photoIds', 'repairIds']);
    const repairIds = strings(item.repairIds, 30); unique(repairIds);
    if (repairIds.some(id => !observedDamage.some(damage => damage.id === id))) throw new AnalysisValidationError();
    return {id:identifier(item.id), title:text(item.title,240), description:text(item.description), photoIds:evidence(item.photoIds), repairIds};
  });
  unique(proposedWork.map(item => item.id));
  // One grouped work item can include several repairs; a repair must not be charged/listed twice.
  unique(proposedWork.flatMap(item => item.repairIds));
  const quantitiesRow = object(row.quantities, ['doors', 'drawers']);
  const quantities = {doors:quantity(quantitiesRow.doors,context.doorCount), drawers:quantity(quantitiesRow.drawers,context.drawerCount)};
  let outcome = choice(row.outcome, ['analysis_ready','additional_photos_required','site_review_required'] as const);
  const missingRequired = coverage.some(item => !item.covered && !(item.role === 'upper' && context.coverage.upperNotApplicable) && !(item.role === 'damage' && context.coverage.damageNotPresent));
  if (missingRequired || photoQuality.some(item => !item.usable)) outcome = 'additional_photos_required';
  else if (quantities.doors.needsConfirmation || quantities.drawers.needsConfirmation) outcome = 'site_review_required';
  return {summary:text(row.summary,2400),outcome,photoQuality,coverage,observedDamage,quantities,proposedWork,unknowns:strings(row.unknowns,20),siteChecks:strings(row.siteChecks,20)};
}

// Single schema contract consumed by the provider. Additional properties are denied at every object.
const stringSchema = {type:'string'};
const stringArray = {type:'array',items:stringSchema};
const nullableString = {type:['string','null']};
const objectSchema = (properties: Record<string, unknown>) => ({type:'object',properties,required:Object.keys(properties),additionalProperties:false});
const arraySchema = (items: unknown) => ({type:'array',items});
const quantitySchema = objectSchema({observed:{type:['integer','null']},customer:{type:['integer','null']},needsConfirmation:{type:'boolean'}});
// A declaration that a view is not applicable is not photographic evidence.
// Mirror the existing validator invariant in the provider's constrained output.
const coverageSchema = {anyOf:[true,false].map(covered => objectSchema({
  role:{type:'string',enum:PHOTO_ROLES},
  covered:{type:'boolean',enum:[covered]},
  photoIds:{...stringArray,minItems:covered?1:0,maxItems:8},
  note:stringSchema,
}))};
export const PHOTO_ANALYSIS_JSON_SCHEMA = objectSchema({
  summary:stringSchema,
  outcome:{type:'string',enum:['analysis_ready','additional_photos_required','site_review_required']},
  photoQuality:arraySchema(objectSchema({photoId:stringSchema,usable:{type:'boolean'},issues:stringArray,retakeInstruction:nullableString})),
  coverage:arraySchema(coverageSchema),
  observedDamage:arraySchema(objectSchema({id:stringSchema,kind:{type:'string',enum:['peeling','chipping','cracking','swelling','joint_gap','other']},location:stringSchema,description:stringSchema,photoIds:stringArray,severity:{type:'string',enum:['minor','moderate','severe']}})),
  quantities:objectSchema({doors:quantitySchema,drawers:quantitySchema}),
  proposedWork:arraySchema(objectSchema({id:stringSchema,title:stringSchema,description:stringSchema,photoIds:stringArray,repairIds:stringArray})),
  unknowns:stringArray,siteChecks:stringArray,
});
